 /* ══ enlace del QR: si la URL trae ?origen=&destino=, se precarga la ruta ══
    Así, al escanear el código desde el kiosco, el celular abre esta misma
    página y traza la ruta de inmediato, sin que el visitante toque nada.
    Blindado con reintentos: en un <select>, asignar .value a algo que
    todavía no tiene su <option> correspondiente NO lo cambia — se queda
    en blanco en silencio. Si llenarSelects() tardara una fracción más en
    poblar las opciones, antes esto fallaba sin avisar nada. Ahora se
    reintenta varias veces y, si de verdad no se puede, se avisa en pantalla
    (para poder diagnosticarlo sin consola, directamente desde el celular). */
 if(ES_MOVIL){
  try{
   const qp=new URLSearchParams(window.location.search);
   const qo=qp.get('origen'), qd=qp.get('destino');
   /* ══ resolución robusta por nombre ══
      El kiosco (datos en vivo del servidor) y GitHub (catálogo de
      respaldo fijo) pueden traer los locales en orden distinto. Un
      índice numérico plano ("destino=45") puede apuntar a un local
      diferente en cada lado — eso era justo lo que causaba "no se pudo
      precargar la ruta". 'K' (kiosco) y 'B#' (edificio) son estables y
      no necesitan esto; solo el índice numérico de un local se corrige
      aquí, buscándolo por su nombre (y proyecto, para desempatar). */
   function resolverValorQR(val,nombre,proy){
    if(!val || val==='K' || /^B\d+$/.test(val)) return val;
    const idx=+val;
    if(!isNaN(idx) && POIS[idx] && nombre && POIS[idx].n===nombre) return val;
    if(nombre){
     for(let i=0;i<POIS.length;i++) if(POIS[i].n===nombre && (!proy || POIS[i].p===proy)) return String(i);
     for(let i=0;i<POIS.length;i++) if(POIS[i].n===nombre) return String(i);
    }
    return val;
   }
   const qoR=resolverValorQR(qo, qp.get('on'), qp.get('op'));
   const qdR=resolverValorQR(qd, qp.get('dn'), qp.get('dp'));
   if(qo!==null && qd!==null && qo!=='' && qd!==''){
    document.getElementById('landing').style.display='none';
    setMini(false);
    let intentos=0;
    (function aplicarRutaDesdeQR(){
     intentos++;
     const f=document.getElementById('from'), t=document.getElementById('to');
     f.value=qoR; t.value=qdR;
     const quedo=(f.value===qoR && t.value===qdR);
     if(!quedo && intentos<8){ setTimeout(aplicarRutaDesdeQR,200); return }
     if(!quedo){
      avisar('No se pudo precargar la ruta del enlace — selecciónala manualmente',true);
      return;
     }
     revisarFab();
     setTimeout(function(){
      const btn=document.getElementById('calc');
      if(btn) btn.click();
     },250);
    })();
   }
  }catch(e){ console.info('Cayalá · no se pudo leer la ruta del enlace',e.message) }
 }
