/* ══════════════ LA RUTA, DIBUJADA PASO A PASO ══════════════ */
let rafRuta=null;
function dibujarRuta(co){
 if(rafRuta) cancelAnimationFrame(rafRuta);
 const acc=acumDist(co), tot=acc[acc.length-1];
 if(!tot){map.getSource('route').setData({type:'FeatureCollection',
  features:[{type:'Feature',geometry:{type:'LineString',coordinates:co}}]});return}
 const dur=Math.min(1600,Math.max(750,tot*5));
 const t0=performance.now();
 function paso(t){
  const k=Math.min(1,(t-t0)/dur);
  const e=1-Math.pow(1-k,3);            /* desaceleración suave */
  const d=tot*e;
  /* porción del trazo ya recorrida */
  const parcial=[co[0]];
  let i=1;
  while(i<acc.length && acc[i]<d){parcial.push(co[i]);i++}
  if(i<co.length){
   const seg=Math.max(acc[i]-acc[i-1],1e-9);
   const f=(d-acc[i-1])/seg;
   const p1=co[i-1],p2=co[i];
   parcial.push([p1[0]+(p2[0]-p1[0])*f, p1[1]+(p2[1]-p1[1])*f]);
  }
  map.getSource('route').setData({type:'FeatureCollection',
   features:[{type:'Feature',geometry:{type:'LineString',coordinates:parcial}}]});
  if(k<1) rafRuta=requestAnimationFrame(paso);
  else rafRuta=null;
 }
 rafRuta=requestAnimationFrame(paso);
}
/* jalones cada 50 m sobre el trazo */
function marcasDistancia(co){
 const acc=acumDist(co), tot=acc[acc.length-1];
 const f=[];
 for(let d=50; d<tot-18; d+=50){
  const q=puntoEn(co,acc,d);
  f.push({type:'Feature',geometry:{type:'Point',coordinates:q.p},
   properties:{m:Math.round(d)+' m'}});
 }
 if(map.getSource('hitos')) map.getSource('hitos').setData({type:'FeatureCollection',features:f});
 pintarHitos(f);
}
const hitosEl=[];
function pintarHitos(feats){
 hitosEl.forEach(function(h){h.el.remove()}); hitosEl.length=0;
 feats.forEach(function(f){
  const el=document.createElement('div');
  el.className='hito'; el.textContent=f.properties.m;
  document.getElementById('map').appendChild(el);
  hitosEl.push({el:el,c:f.geometry.coordinates});
 });
 moverHitos();
}
function moverHitos(){
 const z=map.getZoom(), vis=z>=16.4 && !paseo.on;
 hitosEl.forEach(function(h){
  if(!vis){h.el.style.display='none';return}
  const p=map.project(h.c);
  h.el.style.display='block';
  h.el.style.left=p.x+'px'; h.el.style.top=p.y+'px';
 });
}
function limpiarHitos(){
 hitosEl.forEach(function(h){h.el.remove()}); hitosEl.length=0;
}
/* ══════════════ RECORRIDO EN PRIMERA PERSONA ══════════════ */
function acumDist(co){
 const a=[0];
 for(let i=1;i<co.length;i++) a.push(a[i-1]+hav(co[i-1],co[i]));
 return a}
/* asocia cada indicación con la distancia a la que ocurre */
function pasosConDistancia(co,st,PA,PB){
 const lista=[{d:0,ic:'▶',tx:'Sal de '+PA.n,idx:0}];
 let acum=0;
 st.forEach(function(s,i){ acum+=s.m;
  lista.push({d:acum,ic:s.ic,tx:s.t,idx:i+1})});
 lista.push({d:rutaTot,ic:'◉',tx:'Llegada · '+PB.n,idx:st.length+1});
 return lista}
/* punto y rumbo a una distancia dada del recorrido */
function puntoEn(co,acc,d){
 const n=co.length;
 if(n<2) return {p:co[0],b:0};
 if(d<=0)  return {p:co[0],b:bearng(co[0],co[1])};
 const tot=acc[acc.length-1];
 if(d>=tot) return {p:co[n-1],b:bearng(co[n-2],co[n-1])};
 let i=1; while(i<acc.length-1 && acc[i]<d) i++;
 const seg=Math.max(acc[i]-acc[i-1],1e-9);
 const t=(d-acc[i-1])/seg;
 const a=co[i-1],b=co[i];
 return {p:[a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t], b:bearng(a,b)}}
/* interpolación angular corta (evita el salto 359°→0°) */
function lerpAng(a,b,t){
 let d=((b-a+540)%360)-180;
 return (a+d*t+360)%360}
let bearingSuave=null;
function marcarPasoActual(d){
 if(!rutaPasos.length) return;
 let act=0;
 for(let i=0;i<rutaPasos.length;i++) if(d>=rutaPasos[i].d-0.5) act=i;
 const pasos=document.querySelectorAll('#steps .step');
 pasos.forEach(function(el,i){el.classList.toggle('now',i===act)});
 if(pasos[act]) pasos[act].scrollIntoView({block:'nearest'});
 const hud=document.getElementById('walkHud');
 const p=rutaPasos[act];
 const rest=Math.max(0,Math.round(rutaTot-d));
 hud.innerHTML='<span class="ic">'+p.ic+'</span><span class="tx">'+p.tx+'</span>'+
  '<div class="mt">'+rest+' M RESTANTES</div>';
 hud.classList.add('on')}
function pasoPaseo(ts){
 if(!paseo.on) return;
 if(paseo.pausa){ paseo.t0=ts; paseo.raf=requestAnimationFrame(pasoPaseo); return }
 const dt=Math.min(0.1,(ts-paseo.t0)/1000); paseo.t0=ts;
 paseo.d += paseo.vel*dt;
 if(paseo.d>=rutaTot){ paseo.d=rutaTot; finPaseo(); return }
 const q=puntoEn(rutaCo,rutaAcc,paseo.d);
 /* mira un poco más adelante para que el giro se anticipe */
 const ade=puntoEn(rutaCo,rutaAcc,Math.min(rutaTot,paseo.d+7));
 bearingSuave = bearingSuave===null ? q.b : lerpAng(bearingSuave,ade.b,0.08);
 map.jumpTo({center:q.p,bearing:bearingSuave,pitch:76,zoom:20.2});
 document.getElementById('wFill').style.width=(100*paseo.d/rutaTot)+'%';
 marcarPasoActual(paseo.d);
 paseo.raf=requestAnimationFrame(pasoPaseo)}
function iniciarPaseo(){
 if(!rutaCo||rutaCo.length<2) return;
 paseo.on=true; paseo.pausa=false; paseo.d=0; bearingSuave=null;
 paseo.vel=parseFloat(document.getElementById('wSpeed').value)||6;
 document.body.classList.add('walking'); ajustarMargen(); cerrarGaleria();
 if(map.getSource('bldhov')) map.getSource('bldhov').setData({type:'FeatureCollection',features:[]});
 document.getElementById('wPlay').style.display='none';
 document.getElementById('wCtl').classList.add('on');
 document.getElementById('wToggle').textContent='⏸';
 map.getSource('bld').setData(bldFC()); marcarTags();
 const q=puntoEn(rutaCo,rutaAcc,0);
 map.easeTo({center:q.p,bearing:q.b,pitch:76,zoom:20.2,duration:1300});
 setTimeout(function(){
  if(!paseo.on)return;
  paseo.t0=performance.now();
  paseo.raf=requestAnimationFrame(pasoPaseo)},1350)}
function finPaseo(){
 paseo.on=false;
 if(paseo.raf) cancelAnimationFrame(paseo.raf);
 document.getElementById('wFill').style.width='100%';
 const hud=document.getElementById('walkHud');
 hud.innerHTML='<span class="ic">◉</span><span class="tx">Has llegado a tu destino</span>';
 setTimeout(function(){hud.classList.remove('on')},2600);
 setTimeout(function(){salirPaseo()},2000)}
function pararPaseo(){
 paseo.on=false; paseo.pausa=false;
 if(paseo.raf) cancelAnimationFrame(paseo.raf);
 document.body.classList.remove('walking'); ajustarMargen();
 document.getElementById('walkHud').classList.remove('on');
 document.getElementById('wCtl').classList.remove('on');
 document.getElementById('wPlay').style.display='flex';
 document.getElementById('wFill').style.width='0%';
 document.querySelectorAll('#steps .step').forEach(function(el){el.classList.remove('now')})}
function salirPaseo(){
 pararPaseo();
 map.getSource('bld').setData(bldFC()); marcarTags();
 if(rutaCo){
  const xs=rutaCo.map(function(c){return c[0]}),ys=rutaCo.map(function(c){return c[1]});
  map.fitBounds([[Math.min.apply(null,xs),Math.min.apply(null,ys)],[Math.max.apply(null,xs),Math.max.apply(null,ys)]],
   {padding:150,maxZoom:18.6,pitch:0,bearing:rumboCercanoRuta(rutaCo),duration:1100});
  document.getElementById('v2d').classList.add('on');document.getElementById('v3d').classList.remove('on')}}
document.getElementById('wPlay').onclick=iniciarPaseo;
document.getElementById('wExit').onclick=salirPaseo;
/* botón flotante de emergencia: el de arriba (wExit) queda inalcanzable
   porque vive dentro de #panel, que se oculta durante la caminata */
const walkExitEl=document.getElementById('walkExit');
if(walkExitEl) walkExitEl.onclick=salirPaseo;
document.getElementById('wRestart').onclick=function(){
 paseo.d=0; bearingSuave=null; paseo.pausa=false;
 document.getElementById('wToggle').textContent='⏸'};
document.getElementById('wToggle').onclick=function(){
 paseo.pausa=!paseo.pausa;
 this.textContent=paseo.pausa?'▶':'⏸'};
document.getElementById('wSpeed').onchange=function(){
 paseo.vel=parseFloat(this.value)||6};
document.getElementById('wBar').onclick=function(e){
 if(!paseo.on||!rutaTot)return;
 const r=this.getBoundingClientRect();
 paseo.d=Math.max(0,Math.min(rutaTot,rutaTot*(e.clientX-r.left)/r.width));
 document.getElementById('wFill').style.width=(100*paseo.d/rutaTot)+'%'};
document.addEventListener('keydown',function(e){
 if(!paseo.on)return;
 if(e.key==='Escape') salirPaseo();
 if(e.key===' '){e.preventDefault();document.getElementById('wToggle').click()}});
/* ════════════ ESTADO DEL DIRECTORIO ════════════ */
const LS_KEY = 'cayala_admin_v3';
const LS_OLD = 'cayala_admin_v2';
const POIS_BASE = JSON.parse(JSON.stringify(POIS));   /* copia original intacta */
function saveAdminState(){
 try{localStorage.setItem(LS_KEY, JSON.stringify(POIS))}catch(e){
  avisar('No se pudo guardar: almacenamiento lleno',true)}
}
function loadAdminState(){
 try{
  const raw=localStorage.getItem(LS_KEY);
  if(raw){
   const arr=JSON.parse(raw);
   if(Array.isArray(arr)&&arr.length){
    POIS.length=0; arr.forEach(function(p){POIS.push(p)});
    return}
  }
  /* de la versión anterior solo se conserva qué locales estaban
     ocultos; el resto viene de la base GLA incorporada al archivo */
  const viejo=localStorage.getItem(LS_OLD);
  if(viejo){
   const arr=JSON.parse(viejo);
   if(Array.isArray(arr)){
    const off={};
    arr.forEach(function(x){if(x&&x.active===false&&x.n)off[x.n]=1});
    POIS.forEach(function(p){if(off[p.n])p.active=false});
   }
   localStorage.removeItem(LS_OLD);
   saveAdminState();
  }
 }catch(e){}
}
POIS.forEach(function(p){if(p.active===undefined)p.active=true});
/* con servidor, PostgreSQL es la fuente de verdad: la copia del navegador
   solo se usa en modo autónomo (si no, taparía los datos reales) */
if(!USANDO_API) loadAdminState();
POIS.forEach(function(p){if(p.active===undefined)p.active=true});

/* fp() ya filtraba por categoría/búsqueda; ahora también respeta p.active */
(function(){
 const origFp = fp;
 fp = function(){
  /* los puntos solo aparecen al elegir un edificio o al filtrar:
     de otro modo el mapa se llena de motas de color */
  const explorando = query!=='' || active.size<cats.length;
  if(selB<0 && !explorando) return {type:'FeatureCollection',features:[]};
  const f=[];
  for(let i=0;i<POIS.length;i++){const p=POIS[i];
   if(p.active===false)continue;
   if(selB>=0 && !explorando && p.bi!==selB)continue;
   if(!active.has(p.c))continue;
   if(query){const s=(p.n+' '+p.e+' '+p.p+' '+p.c).toLowerCase();if(s.indexOf(query)<0)continue}
   f.push({type:'Feature',geometry:{type:'Point',coordinates:[p.lon,p.lat]},
    properties:{n:p.n,p:p.p,e:p.e,nv:p.nv,c:p.c,idx:i,col:(COL[p.c]||'#555')}})}
  return{type:'FeatureCollection',features:f}
 };
})();
