(function(){
 const slides=document.querySelectorAll('#landing .slide');
 const caja=document.getElementById('dots');
 if(!slides.length)return;
 let si=0,timer=null;
 if(caja){
  caja.innerHTML=Array.from(slides).map(function(_,i){
   return '<div class="dot'+(i===0?' on':'')+'" data-i="'+i+'"></div>'}).join('');
 }
 const dots=caja?caja.querySelectorAll('.dot'):[];
 function ver(n){
  slides[si].classList.remove('on'); if(dots[si])dots[si].classList.remove('on');
  si=(n+slides.length)%slides.length;
  slides[si].classList.add('on'); if(dots[si])dots[si].classList.add('on');
 }
 function correr(){timer=setInterval(function(){ver(si+1)},6500)}
 dots.forEach(function(d){d.onclick=function(){clearInterval(timer);ver(+d.dataset.i);correr()}});
 correr();
})();
