function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){
 return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}

/* el campo "Usuario" toma la misma apariencia que el de contraseña */
function copiarEstiloUsuario(){
 const u=document.getElementById('adminUser'), p=document.getElementById('adminPass');
 if(!u||!p||u.dataset.estilo) return;
 const cs=getComputedStyle(p);
 ['fontFamily','fontSize','fontWeight','letterSpacing','color','backgroundColor','boxSizing',
  'borderTopWidth','borderTopStyle','borderTopColor','borderRightWidth','borderRightStyle','borderRightColor',
  'borderBottomWidth','borderBottomStyle','borderBottomColor','borderLeftWidth','borderLeftStyle','borderLeftColor',
  'borderTopLeftRadius','borderTopRightRadius','borderBottomLeftRadius','borderBottomRightRadius',
  'paddingTop','paddingRight','paddingBottom','paddingLeft','marginTop','marginRight','marginBottom','marginLeft',
  'height','textAlign'].forEach(function(k){ if(cs[k]) u.style[k]=cs[k] });
 const w=parseFloat(cs.width), pw=p.parentElement?p.parentElement.clientWidth:0;
 u.style.width=(pw&&Math.abs(w-pw)<24)?'100%':cs.width;
 u.dataset.estilo='1';
}
