async function tryLogin(){
 const err=document.getElementById('adminErr');
 const uEl=document.getElementById('adminUser');
 const usuario=uEl?uEl.value.trim():'';
 const clave=document.getElementById('adminPass').value;
 err.style.display='none';
 if(!usuario || !clave){
  err.textContent='Escribe tu usuario y tu contraseña.';
  err.style.display='block'; return }
 if(!USANDO_API){
  err.textContent='Sin conexión con el servidor: no se puede validar el acceso.';
  err.style.display='block'; return }
 try{
  const r=await conTiempoLimite(fetch(API_BASE+'/api/admin/login',{method:'POST',
   headers:{'Content-Type':'application/json'},body:JSON.stringify({usuario:usuario,clave:clave})}),10000);
  let data=null; try{data=await r.json()}catch(e){}
  if(!r.ok || !data || !data.token){
   /* FastAPI devuelve detail como texto, o como lista si el formato es inválido */
   err.textContent=(data&&typeof data.detail==='string')?data.detail:'Usuario o contraseña incorrectos.';
   document.getElementById('adminPass').value='';
   err.style.display='block'; return }
  ADMIN_TOKEN=data.token; sessionStorage.setItem('cayala_token',ADMIN_TOKEN);
  document.getElementById('adminPass').value='';
  if(uEl) uEl.value='';
  adminAuthed=true;
  document.getElementById('adminLogin').classList.add('off');
  document.getElementById('adminPanel').classList.add('on');
  document.getElementById('adminBox').classList.add('wide');
  irSeccion('dash');
  avisar('Sesión iniciada: '+(data.nombre||data.usuario||usuario));
 }catch(e){
  err.textContent='No se pudo contactar al servidor ('+e.message+').';
  err.style.display='block' }
}
