  if(!r.ok){ alert('No se pudo descargar (HTTP '+r.status+')'); return }
  const b=await r.blob(); const u=URL.createObjectURL(b); const l=document.createElement('a');
  l.href=u; l.download='eventos_uso_cayala.csv'; document.body.appendChild(l); l.click(); l.remove();
  setTimeout(function(){URL.revokeObjectURL(u)},2000);
