/* ---------- RENDIMIENTO POR PROYECTO ---------- */
function tablaProyectos(){
 const m=porProyecto();
 const ks=Object.keys(m).sort(function(a,b){return m[b].renta-m[a].renta});
 if(!ks.length) return '<div class="admVacio">Sin datos.</div>';
 const tot={n:0,renta:0,area:0,disp:0};
 ks.forEach(function(k){tot.n+=m[k].n;tot.renta+=m[k].renta;tot.area+=m[k].area;tot.disp+=m[k].disp});
 return '<table class="admTbl"><thead><tr><th>Proyecto</th><th>Locales</th>'+
  '<th>Área</th><th>Renta / mes</th><th>$ por m\u00b2</th><th>Ocupación</th></tr></thead><tbody>'+
  ks.map(function(k){const v=m[k];
   const oc=v.n?100*(v.n-v.disp)/v.n:0;
   return '<tr><td class="nm">'+esc(k)+'</td>'+
    '<td class="mono">'+v.n+'</td>'+
    '<td class="mono">'+M2(v.area)+'</td>'+
    '<td class="mono">'+Q(v.renta)+'</td>'+
    '<td class="mono">'+(v.area?Q2(v.renta/v.area):'\u2014')+'</td>'+
    '<td class="mono">'+oc.toFixed(1)+'%</td></tr>'}).join('')+
  '<tr style="background:#FAF7F1;font-weight:700">'+
   '<td class="nm">Total</td><td class="mono">'+tot.n+'</td>'+
   '<td class="mono">'+M2(tot.area)+'</td><td class="mono">'+Q(tot.renta)+'</td>'+
   '<td class="mono">'+(tot.area?Q2(tot.renta/tot.area):'\u2014')+'</td>'+
   '<td class="mono">'+(tot.n?(100*(tot.n-tot.disp)/tot.n).toFixed(1):'0')+'%</td></tr>'+
  '</tbody></table>'}
/* ---------- RED PEATONAL ---------- */
function redPeatonal(){
 const n=NODES.length, a=EDGES.length, m=D.red_m||0;
 /* longitud media de tramo */
 const medio = a ? (m/a) : 0;
 /* grado medio: cuántos tramos confluyen en cada nodo */
 const grado = n ? (2*a/n) : 0;
 /* comprobación de conectividad: recorrido en anchura */
 const ady={};
 EDGES.forEach(function(e){(ady[e[0]]=ady[e[0]]||[]).push(e[1]);(ady[e[1]]=ady[e[1]]||[]).push(e[0])});
 const visto=new Set(); let comp=0;
 for(let i=0;i<n;i++){
  if(visto.has(i)||!ady[i]) continue;
  comp++; const pila=[i]; visto.add(i);
  while(pila.length){const u=pila.pop();
   (ady[u]||[]).forEach(function(v){if(!visto.has(v)){visto.add(v);pila.push(v)}})}
 }
 const conexo = comp===1;
 return '<div class="admKpis" style="margin-bottom:18px">'+
  '<div class="admKpi"><b>'+m.toLocaleString('es')+'</b><span>Metros digitalizados</span>'+
   '<div class="dt">'+(D.lines?D.lines.length:0)+' tramos en QGIS</div></div>'+
  '<div class="admKpi"><b>'+n+'</b><span>Nodos del grafo</span>'+
   '<div class="dt">Intersecciones y extremos</div></div>'+
  '<div class="admKpi"><b>'+a+'</b><span>Aristas</span>'+
   '<div class="dt">'+medio.toFixed(1)+' m de media</div></div>'+
  '<div class="admKpi"><b>'+(conexo?'1':comp)+'</b><span>Componente'+(conexo?'':'s')+'</span>'+
   '<div class="dt">'+(conexo?'Grafo conexo':'Revisar continuidad')+'</div></div>'+
 '</div>'+
 '<p style="font-size:12px;color:#5E574B;line-height:1.75;margin:0">'+
 'La red se digitalizó sobre el plano georreferenciado y se convirtió en un grafo no dirigido: '+
 'los tramos se segmentaron en sus intersecciones y los extremos coincidentes se unificaron dentro '+
 'de una tolerancia de 8&nbsp;m. El peso de cada arista es su longitud geodésica, y las rutas se '+
 'resuelven con el algoritmo de Dijkstra. Cada nodo tiene en promedio '+grado.toFixed(1)+' conexiones'+
 (conexo?', y la verificación confirma un único componente conexo: existe ruta entre cualquier par de locales.':'.')+
 '</p>';
}
