function puntoEnEdificio(bi){
 const b=BLD[bi];
 if(!b) return null;
 const c=centro(b.c);
 const hay=POIS.filter(function(p){return p.bi===bi});
 const n=hay.length, ang=2*Math.PI*n/Math.max(n+1,6), r=0.000024;
 return {lon:+(c[0]+r*Math.sin(ang)/Math.cos(c[1]*Math.PI/180)).toFixed(7),
         lat:+(c[1]+r*Math.cos(ang)).toFixed(7)};
}
