window.modoImg=function(m){imgModo=m;imgFiltro='';pintarImagenes()};
/* recorte 16:9 a 1200 px, común a fachadas y comercios */
function recortar169(file,cb){
 const im=new Image();
 im.onload=function(){
  const W=1200,H=675,cv=document.createElement('canvas'); cv.width=W; cv.height=H;
  const r=im.width/im.height, rt=W/H; let sw=im.width,sh=im.height,sx=0,sy=0;
  if(r>rt){sw=im.height*rt;sx=(im.width-sw)/2}else{sh=im.width/rt;sy=(im.height-sh)/2}
  cv.getContext('2d').drawImage(im,sx,sy,sw,sh,0,0,W,H);
  URL.revokeObjectURL(im.src);
  cv.toBlob(cb,'image/jpeg',0.82)};
 im.onerror=function(){avisar('No se pudo leer la imagen',true)};
 im.src=URL.createObjectURL(file)}
function pintarImagenesPoi(){
 const lista=POIS.map(function(p,i){return{p:p,i:i}}).filter(function(o){return o.p.active!==false});
 const con=lista.filter(function(o){return fotoComercio(o.p)}).length;
 let vis=lista.filter(function(o){
  if(imgQ && (o.p.n+' '+o.p.e+' '+o.p.p).toLowerCase().indexOf(imgQ)<0) return false;
  if(imgFiltro==='con') return !!fotoComercio(o.p);
  if(imgFiltro==='sin') return !fotoComercio(o.p);
  return true}).sort(function(a,b){return a.p.n.localeCompare(b.p.n,'es')});
 const on=' style="border-color:var(--gold);background:rgba(192,160,98,.1)"';
 document.getElementById('sec-imagenes').innerHTML=
 '<div class="admH">Imágenes</div><div class="admSub">Fotografía de cada comercio</div>'+
 '<div class="admKpis">'+
  '<div class="admKpi"><b>'+con+'</b><span>Con fotografía</span><div class="dt">de '+lista.length+' comercios activos</div></div>'+
  '<div class="admKpi"><b>'+(lista.length-con)+'</b><span>Pendientes</span><div class="dt">No se muestra nada vacío en el mapa</div></div>'+
 '</div>'+ selectorModoImg()+
 '<div class="admTools"><input type="search" id="imgQ" placeholder="Buscar comercio..." value="'+esc(imgQ)+'"></div>'+
 '<div class="admChips">'+
  '<div class="admChip" onclick="filtroImg(\'\')"'+(imgFiltro===''?on:'')+'>Todos<b>'+lista.length+'</b></div>'+
  '<div class="admChip" onclick="filtroImg(\'con\')"'+(imgFiltro==='con'?on:'')+'>Con foto<b>'+con+'</b></div>'+
  '<div class="admChip" onclick="filtroImg(\'sin\')"'+(imgFiltro==='sin'?on:'')+'>Pendientes<b>'+(lista.length-con)+'</b></div></div>'+
 '<div class="admImgs">'+vis.slice(0,120).map(function(o){
  const p=o.p, f=fotoComercio(p);
  return '<div class="admImg"><div class="ph">'+
   (f?'<img src="'+f.src+'" alt="" loading="lazy" onerror="this.style.display=\'none\'"><span class="ori">'+f.ori+'</span>'
     :'<span class="vacio">Sin fotografía</span>')+
   '<span class="et">'+esc(p.e||'\u2014')+'</span></div>'+
   '<div class="pie"><b>'+esc(p.n)+'</b><span>'+esc(p.p)+' \u00b7 '+esc(p.nv)+'</span>'+
   '<div class="acc"><label>'+(f?'Cambiar':'Cargar')+
    '<input type="file" accept="image/*" onchange="subirImgPoi(this,'+o.i+')"></label>'+
    (f&&f.ori!=='archivo'?'<button onclick="quitarImgPoi('+o.i+')">Quitar</button>':'')+
   '</div></div></div>'}).join('')+'</div>'+
 (vis.length>120?'<div class="admPie"><span>Mostrando 120 de '+vis.length+' · usa el buscador</span></div>':'');
 const q=document.getElementById('imgQ');
 if(q) q.oninput=function(){imgQ=this.value.toLowerCase().trim();const pos=this.selectionStart;
  pintarImagenes();const n=document.getElementById('imgQ');n.focus();n.setSelectionRange(pos,pos)}}
function refrescarFotoPoi(p){
 pintarImagenes();
 if(p.bi>=0 && selB===p.bi && typeof mostrarPills==='function') mostrarPills(p.bi)}
window.subirImgPoi=function(input,i){
 const file=input.files&&input.files[0]; input.value='';
 if(!file) return;
 if(!/^image\//.test(file.type)){avisar('Ese archivo no es una imagen',true);return}
 const p=POIS[i], k=String(p.n).toUpperCase();
 recortar169(file,async function(blob){
  if(USANDO_API && p.id){
   const fd=new FormData(); fd.append('file',blob,'comercio-'+p.id+'.jpg');
   const r=await apiAdmin('/api/admin/imagen/poi/'+p.id,'POST',fd);
   if(r.ok){ FOTOS_POI_SRV[k]={src:API_BASE+r.data.url+'?v='+Date.now()};
    delete IMG_POI_LOCAL[k]; refrescarFotoPoi(p);
    avisar('Foto de '+p.n+' subida al servidor'); return }
  }
  const fr=new FileReader();
  fr.onload=function(ev){ IMG_POI_LOCAL[k]=ev.target.result;
   try{localStorage.setItem(LS_IMG_POI,JSON.stringify(IMG_POI_LOCAL))}
   catch(e){avisar('No cabe la imagen en el navegador',true);return}
   refrescarFotoPoi(p);
   avisar('Guardada solo en este navegador \u00b7 sin conexi\u00f3n al servidor',true)};
  fr.readAsDataURL(blob)})};
window.quitarImgPoi=async function(i){
 const p=POIS[i], k=String(p.n).toUpperCase();
 delete FOTOS_POI_SRV[k]; delete IMG_POI_LOCAL[k];
 try{localStorage.setItem(LS_IMG_POI,JSON.stringify(IMG_POI_LOCAL))}catch(e){}
 refrescarFotoPoi(p); avisar('Foto retirada');
 if(USANDO_API && p.id) await apiAdmin('/api/admin/imagen/poi/'+p.id,'DELETE')};
window.subirImg=function(input,bi){
 const file=input.files&&input.files[0];
 if(!file) return;
 if(!/^image\//.test(file.type)){avisar('Ese archivo no es una imagen',true);return}
 const k=claveEdif(bi);
 if(!k){avisar('Ese bloque no es un edificio con c\u00f3digo',true);return}
 const im=new Image();
 im.onload=function(){
  const W=1200,H=675;
  const cv=document.createElement('canvas'); cv.width=W; cv.height=H;
  const cx=cv.getContext('2d');
  const r=im.width/im.height, rt=W/H;
  let sw=im.width, sh=im.height, sx=0, sy=0;
  if(r>rt){ sw=im.height*rt; sx=(im.width-sw)/2 }
  else    { sh=im.width/rt;  sy=(im.height-sh)/2 }
  cx.drawImage(im,sx,sy,sw,sh,0,0,W,H);
  URL.revokeObjectURL(im.src);
  const idEd=idEdificioBackend(bi);
  cv.toBlob(async function(blob){
   let subida=false;
   if(USANDO_API && idEd!=null){
    const fd=new FormData(); fd.append('file',blob,k.replace('|','-')+'.jpg');
    const r=await apiAdmin('/api/admin/imagen/edificio/'+idEd,'POST',fd);
    if(r.ok){
     FOTOS_EDIF_SRV[k]={src:API_BASE+r.data.url, ori:'servidor'};
     subida=true;
     pintarImagenes();
     if(selB===bi && typeof mostrarPills==='function') mostrarPills(bi);
     avisar('Fachada subida al servidor: '+k.split('|')[1]);
    }
   }
   if(!subida){
    const fr=new FileReader();
    fr.onload=function(ev){
     IMG_LOCAL[k]=ev.target.result;
     guardarImgs(); pintarImagenes();
     if(selB===bi && typeof mostrarPills==='function') mostrarPills(bi);
     avisar('Guardada solo en este navegador \u00b7 sin conexi\u00f3n al servidor', true);
    };
    fr.readAsDataURL(blob);
   }
  }, 'image/jpeg', 0.82);
 };
 im.onerror=function(){avisar('No se pudo leer la imagen',true)};
 im.src=URL.createObjectURL(file);
 input.value=''};
window.quitarImg=async function(bi){
 const k=claveEdif(bi); if(!k) return;
 delete IMG_LOCAL[k]; guardarImgs();
 delete FOTOS_EDIF_SRV[k];
 pintarImagenes();
 if(selB===bi && typeof mostrarPills==='function') mostrarPills(bi);
 avisar('Imagen retirada');
 const idEd=idEdificioBackend(bi);
 if(USANDO_API && idEd!=null){ await apiAdmin('/api/admin/imagen/edificio/'+idEd,'DELETE') }};

